<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {localFetch,readJson} from './http'
import {segments} from './marginChecker'
type Breadth={above:number;unknown:number;universe:number;lower:number|null;upper:number|null;below10:boolean|null}
type Point={date:string;relative_day:number;phase:string;official_loan:number|null;loan_change1:number|null;decline5:number|null;index_close:number|null;index_return_pct:number|null;breadth:Breadth;price_effect_pp:number|null;inventory_effect_pp:number|null}
type Outcome={horizon:number;status:string;return_pct:number|null;minimum_close_return_pct:number|null}
type Episode={id:string;first:string;last:string;trigger_days:number;closure:string;maturity:string;pre_days:number;post_days:number;missing_index_days:number;missing_loan_days:number;overlap:boolean;decline5_at_start:number;threshold_at_start:number;reference_n:number;anchor_close:number|null;outcomes:Outcome[];points:Point[]}
type Market={market:string;date:string;official_days:number;index_days:number;breadth_days:number;eligible_model_days:number;days:number;primary:{cleaning:{status:string;confirmed_count:null};divergence:{status:string;confirmed_count:null;consecutive_days:null}};observation:{label:string;eligible_days:number;trigger_days:number;episodes:Episode[];latest_decline5:number|null;latest_reference:{threshold:number|null;n:number;valid:boolean;reason:string|null};latest_breadth:Breadth;latest_index:number|null};blockers:string[]}
type Report={version:string;status:string;model_ready:boolean;dates:string[];source_as_of:string;as_of:string;created_at:string;vintage:string;index_sources:Record<string,{label:string}>;frame:{date:string;markets:Market[]}}
const props=defineProps<{asOf?:string}>()
const data=ref<Report|null>(null),day=ref(''),market=ref('TPEX'),selected=ref(''),error=ref(''),loading=ref(false),open=ref(true),hover=ref<number|null>(null),scroll=ref<HTMLDivElement|null>(null)
let request=0,disposed=false
const chosen=computed(()=>data.value?.frame.markets.find(m=>m.market===market.value))
const cases=computed(()=>chosen.value?.observation.episodes||[])
const detail=computed(()=>cases.value.find(e=>e.id===selected.value)||cases.value[0])
const points=computed(()=>detail.value?.points||[])
const activeIndex=computed(()=>hover.value??Math.max(0,points.value.findIndex(p=>p.relative_day===0)))
const active=computed(()=>points.value[activeIndex.value])
const fmt=(x:number|null|undefined,d=2)=>x==null?'—':x.toLocaleString('zh-TW',{maximumFractionDigits:d})
const pct=(x:number|null|undefined)=>x==null?'—':fmt(x*100)+'%'
const directPct=(x:number|null|undefined)=>x==null?'—':fmt(x)+'%'
const money=(x:number|null|undefined)=>x==null?'—':Math.abs(x)>=1e8?fmt(x/1e8)+' 億':Math.abs(x)>=1e4?fmt(x/1e4)+' 萬':fmt(x)+' 元'
const breadthText=(b:Breadth|undefined)=>!b||b.lower==null?'—':b.unknown?pct(b.lower)+' ～ '+pct(b.upper):pct(b.lower)
const maturity=(s:string)=>(({ongoing:'仍在持續',interrupted:'資料中斷',immature:'觀測期未滿',missing:'行情有缺漏',complete:'觀測窗完整'} as Record<string,string>)[s]||s)
const outcomeLabel=(s:string)=>(({immature:'尚未滿期',missing:'缺指數行情',ready:'已有結果'} as Record<string,string>)[s]||s)
const width=computed(()=>Math.max(880,points.value.length*18+100)),left=72,right=30
const x=(i:number)=>left+i/Math.max(1,points.value.length-1)*(width.value-left-right)
function extent(values:(number|null)[]){const a=values.filter((v):v is number=>v!=null&&Number.isFinite(v));if(!a.length)return [-1,1];const lo=Math.min(...a),hi=Math.max(...a),pad=Math.max((hi-lo)*.12,Math.abs(hi)*.01,.1);return [lo-pad,hi+pad]}
const indexRange=computed(()=>extent(points.value.map(p=>p.index_return_pct))),loanRange=computed(()=>extent(points.value.map(p=>p.official_loan==null?null:p.official_loan/1e8)))
const py=(v:number)=>205-(v-indexRange.value[0]!)/(indexRange.value[1]!-indexRange.value[0]!)*155
const ly=(v:number)=>380-(v-loanRange.value[0]!)/(loanRange.value[1]!-loanRange.value[0]!)*105
const pricePaths=computed(()=>segments(points.value.map(p=>p.index_return_pct),x,py))
const loanPaths=computed(()=>segments(points.value.map(p=>p.official_loan==null?null:p.official_loan/1e8),x,ly))
const triggerStart=computed(()=>points.value.findIndex(p=>p.relative_day===0)),triggerEnd=computed(()=>{for(let i=points.value.length-1;i>=0;i--)if(points.value[i]?.phase==='trigger')return i;return -1})
const ticks=computed(()=>[...new Set([0,Math.floor((points.value.length-1)/2),points.value.length-1])].filter(i=>i>=0))
function remember(){try{localStorage.setItem('margin-events.preferences.v1',JSON.stringify({market:market.value,selected:selected.value,open:open.value}))}catch{}}
function toggle(e:Event){open.value=(e.target as HTMLDetailsElement).open;remember()}
async function resetView(){hover.value=null;await nextTick();if(scroll.value)scroll.value.scrollLeft=Math.max(0,x(triggerStart.value)-scroll.value.clientWidth/2)}
function select(e:Episode){selected.value=e.id;remember();resetView()}
function chooseMarket(m:string){market.value=m;selected.value='';remember();resetView()}
function move(e:PointerEvent){const box=(e.currentTarget as SVGElement).getBoundingClientRect(),pos=(e.clientX-box.left)/box.width*width.value;hover.value=Math.max(0,Math.min(points.value.length-1,Math.round((pos-left)/(width.value-left-right)*Math.max(1,points.value.length-1))))}
async function load(){const id=++request;loading.value=true;error.value='';try{const r=await localFetch('/api/margin-statistics/events'+((props.asOf||day.value)?'?date='+encodeURIComponent(props.asOf||day.value):'')),v=await readJson<Report&{error?:string}>(r);if(!r.ok)throw Error(v.error||'讀取事件封存失敗');if(id===request&&!disposed){data.value=v;await resetView()}}catch(e){if(id===request&&!disposed)error.value=e instanceof Error?e.message:String(e)}finally{if(id===request&&!disposed)loading.value=false}}
onMounted(()=>{try{const p=JSON.parse(localStorage.getItem('margin-events.preferences.v1')||'{}');if(['TWSE','TPEX'].includes(p.market))market.value=p.market;if(typeof p.selected==='string')selected.value=p.selected;if(typeof p.open==='boolean')open.value=p.open}catch{};load()})
watch(()=>props.asOf,()=>load())
onUnmounted(()=>{disposed=true;request++})
</script>
<template>
 <section class="events-study" aria-label="包6與7融資事件研究">
  <header><div><div class="eyebrow">FINANCING · EVENT STUDIES</div><h2>清洗與背離 · 逐事件觀察</h2><p>固定門檻，逐段看前後過程；保留未成熟與缺漏，不彙整為交易勝率。</p></div><span class="badge">包6／7 · 模型訊號待驗收</span></header>
  <p v-if="error" class="notice error" role="alert">{{error}} <button @click="load">重新讀取</button></p>
  <p v-if="data?.status==='missing'" class="notice">事件研究封存尚未建立；開啟本頁不會啟動計算。</p>
  <template v-else-if="data?.frame&&chosen">
   <div class="controls"><label v-if="!props.asOf">資料截止日<select v-model="day" aria-label="事件研究截止日" :disabled="loading" @change="load"><option value="">最新封存 · {{data.source_as_of}}</option><option v-for="d in [...data.dates].reverse()" :key="d" :value="d">{{d}}</option></select></label><div class="market-buttons" role="group" aria-label="事件研究市場"><button :aria-pressed="market==='TWSE'" @click="chooseMarket('TWSE')">上市</button><button :aria-pressed="market==='TPEX'" @click="chooseMarket('TPEX')">上櫃</button></div><b class="as-of" :data-events-date="data.as_of">{{data.as_of}}</b><small v-if="loading" role="status">讀取中…</small></div>
   <div class="primary-grid"><article data-primary="cleaning"><div class="rule-title"><span>06</span><h3>機械性回升與清洗</h3><em>尚不可確認</em></div><p>拆出價格效果與籌碼效果；5日籌碼效果為正、融資本金減少，兩項同達各自近兩年前10%，且平均法與FIFO一致。</p><div class="primary-readings"><div><small>價格效果</small><b>—</b></div><div><small>籌碼效果</small><b>—</b></div><div><small>確認事件次數</small><b>—</b></div></div></article><article data-primary="divergence"><div class="rule-title"><span>07</span><h3>融資壓力背離</h3><em>尚不可確認</em></div><p>同市場指數低於前20日所有收盤，但維持率高於期間低點、低130%本金占比低於期間高點，且站上20MA比例低於10%。</p><div class="primary-readings"><div><small>維持率背離</small><b>—</b></div><div><small>連續背離日數</small><b>—</b></div><div><small>確認事件次數</small><b>—</b></div></div></article></div>
   <div class="notice"><b>包2尚未通過，兩種模型訊號都無法驗證。</b><span>可驗證模型日 {{chosen.eligible_model_days}} / {{chosen.days}}；事件次數保留未知。下方只列官方總融資的來源觀測，不判定為清洗、背離或買點。</span></div>
   <details class="method"><summary>查看計算口徑與品質限制</summary><p>價格效果＝昨日餘額按今日收盤重估÷昨日本金−昨日維持率；籌碼效果＝今日維持率−昨日維持率−價格效果。退出部位仍須保留在昨日庫存中重估；缺價格就不計算。</p><p>籌碼效果為正且本金增加時，另記為新資金進場；本金減少時才檢查清洗條件。兩年門檻只用當日前資料，沒有縮短參考窗，也沒有依後續報酬調整。</p><ul><li v-for="r in chosen.blockers" :key="r">{{r}}</li></ul></details>
   <details class="source-study" :open="open" @toggle="toggle" aria-label="官方總融資來源觀測">
    <summary><span>官方總融資極端減少觀測</span><small>含ETF · 非已確認清洗</small></summary>
    <div class="source-body"><div class="source-intro"><b>固定來源條件</b><p>5日融資減幅為正，並達到此前完整兩年的第90百分位。只合併相鄰觸發日；事件前20日、最後觸發日後20日逐筆保留。</p></div>
     <div class="coverage"><div><small>官方總融資來源</small><b>{{chosen.official_days}} / {{chosen.days}} 日</b></div><div><small>{{market==='TWSE'?'加權':'櫃買'}}指數行情</small><b>{{chosen.index_days}} / {{chosen.days}} 日</b></div><div><small>可評估來源條件</small><b>{{chosen.observation.eligible_days}} 日</b></div><div><small>來源觀測段落</small><b>{{chosen.observation.eligible_days?cases.length:'—'}} <em v-if="chosen.observation.eligible_days">段</em></b></div></div>
     <div class="latest-observation"><span>最新5日減幅 <b>{{pct(chosen.observation.latest_decline5)}}</b></span><span>事前90百分位 <b>{{pct(chosen.observation.latest_reference.threshold)}}</b></span><span>站上20MA比例 <b>{{breadthText(chosen.observation.latest_breadth)}}</b></span></div><p class="muted">減幅為正表示融資減少，負數表示增加。20MA使用當日行情表普通股分母，未知成員保留並顯示上下界；最新未知 {{chosen.observation.latest_breadth.unknown}} / {{chosen.observation.latest_breadth.universe}} 檔，未認證完整歷史成員。</p>
     <p v-if="!cases.length" class="empty">{{chosen.observation.eligible_days?'在固定來源條件下，尚無可列的觀測事件。':'尚無完整兩年參考窗可評估，不能解讀為沒有去槓桿事件。'}} {{chosen.observation.latest_reference.reason||''}}</p>
     <template v-else-if="detail"><div class="case-layout"><div class="case-list" role="group" aria-label="融資來源觀測事件名單"><button v-for="c in cases" :key="c.id" :aria-pressed="detail.id===c.id" :data-event-id="c.id" @click="select(c)"><b>{{c.first}}</b><span>～ {{c.last}} · {{c.trigger_days}} 個觸發日</span><small>{{maturity(c.maturity)}}</small></button></div><div class="case-detail"><div class="case-heading"><div><h3>{{detail.first}} ～ {{detail.last}}</h3><p>首日5日減幅 {{pct(detail.decline5_at_start)}} · 當時門檻 {{pct(detail.threshold_at_start)}}（{{detail.reference_n}}筆事前觀測）</p></div><span class="small-badge">{{maturity(detail.maturity)}}</span></div>
       <p class="muted">前 {{detail.pre_days}} / 20 日 · 後 {{detail.post_days}} / 20 日；本窗指數缺 {{detail.missing_index_days}} 日，融資缺 {{detail.missing_loan_days}} 日。<template v-if="detail.overlap">與其他事件的觀測窗重疊，不作獨立試驗計數。</template> 首次觸發日收盤為報酬起點。</p>
       <p v-if="detail.anchor_close==null" class="notice">事件起點缺{{market==='TWSE'?'加權':'櫃買'}}指數行情，指數報酬保留空白，只畫官方融資。</p>
       <div class="chart-readings" :data-event-hover-date="active?.date"><div><small>{{hover==null?'事件起點':'游標日期'}}</small><b>{{active?.date}}</b></div><div><small>官方總融資</small><b>{{money(active?.official_loan)}}</b></div><div><small>{{market==='TWSE'?'加權':'櫃買'}}指數收盤</small><b>{{fmt(active?.index_close)}}</b></div><div><small>相對首日報酬</small><b>{{directPct(active?.index_return_pct)}}</b></div></div>
       <div class="legend"><span><i class="index"></i>{{market==='TWSE'?'加權':'櫃買'}}指數 · 相對首日%</span><span><i class="loan"></i>官方總融資 · 億元</span><span><i class="zone"></i>觸發期間</span></div><p class="muted">可正常左右捲動；游標同步日期與讀數，移開回事件起點。缺漏不連線。</p>
       <div ref="scroll" class="chart-scroll" tabindex="0" aria-label="事件指數與官方融資走勢，可左右捲動"><svg :width="width" height="435" :viewBox="`0 0 ${width} 435`" role="img" aria-label="事件前後指數報酬與官方融資" @pointermove="move" @pointerleave="hover=null"><rect :width="width" height="435" fill="white"/><rect v-if="triggerStart>=0" :x="x(triggerStart)-3" :width="Math.max(6,x(triggerEnd)-x(triggerStart)+6)" y="30" height="350" fill="#f7f1e5"/><text x="12" y="20" class="axis-title">{{market==='TWSE'?'加權':'櫃買'}}指數 · 相對首日%</text><g v-for="tick in [indexRange[0]!,((indexRange[0]!+indexRange[1]!)/2),indexRange[1]!]" :key="tick"><line :x1="left" :x2="width-right" :y1="py(tick)" :y2="py(tick)" class="grid"/><text :x="left-10" :y="py(tick)+4" text-anchor="end" class="tick">{{fmt(tick)}}%</text></g><path v-for="(p,i) in pricePaths" :key="'p'+i" :d="p" class="index-line"/><text v-if="!pricePaths.length" :x="width/2" y="125" text-anchor="middle" class="missing-label">缺少指數行情，未畫連線</text><text x="12" y="255" class="axis-title">官方總融資 · 億元</text><g v-for="tick in [loanRange[0]!,((loanRange[0]!+loanRange[1]!)/2),loanRange[1]!]" :key="tick"><line :x1="left" :x2="width-right" :y1="ly(tick)" :y2="ly(tick)" class="grid"/><text :x="left-10" :y="ly(tick)+4" text-anchor="end" class="tick">{{fmt(tick,1)}}</text></g><path v-for="(p,i) in loanPaths" :key="'l'+i" :d="p" class="loan-line"/><line :x1="x(activeIndex)" :x2="x(activeIndex)" y1="35" y2="380" stroke="#84987c" stroke-dasharray="3 3"/><text v-for="i in ticks" :key="i" :x="x(i)" y="417" :text-anchor="i===0?'start':i===points.length-1?'end':'middle'" class="tick">{{points[i]?.date}}</text></svg></div>
       <div class="table-scroll"><table class="outcomes" aria-label="逐事件後續結果"><thead><tr><th>首日後</th><th>結果狀態</th><th>指數收盤報酬</th><th>期間收盤最大回落</th></tr></thead><tbody><tr v-for="o in detail.outcomes" :key="o.horizon" :data-horizon="o.horizon"><td>{{o.horizon}} 交易日</td><td>{{outcomeLabel(o.status)}}</td><td>{{directPct(o.return_pct)}}</td><td>{{directPct(o.minimum_close_return_pct)}}</td></tr></tbody></table></div><p class="muted">回落按收盤路徑計算，包含起點0%；未滿期與缺行情分開標示。這是描述結果，不代表可成交報酬或因果關係。</p>
       <details class="daily"><summary>檢視事件每日資料</summary><div class="table-scroll"><table><thead><tr><th>日期／相對日</th><th>官方總融資</th><th>單日變化</th><th>5日減幅</th><th>指數收盤</th><th>站上20MA比例</th><th>價格效果</th><th>籌碼效果</th></tr></thead><tbody><tr v-for="p in points" :key="p.date"><td>{{p.date}}<small>{{p.relative_day>0?'+':''}}{{p.relative_day}}日</small></td><td>{{money(p.official_loan)}}</td><td>{{pct(p.loan_change1)}}</td><td>{{pct(p.decline5)}}</td><td>{{fmt(p.index_close)}}</td><td>{{breadthText(p.breadth)}}</td><td>待模型驗收</td><td>待模型驗收</td></tr></tbody></table></div></details>
      </div></div></template>
     <p class="source-note">指數來源：{{data.index_sources[market]?.label}}。官方總融資包含該市場ETF等融資標的，不能直接當成普通股籃子的本金。{{data.vintage}}。</p>
    </div>
   </details><footer>方法 {{data.version}} · 實際保存 {{data.created_at.slice(0,16).replace('T',' ')}} · 唯讀封存</footer>
  </template><p v-else-if="loading" class="muted" role="status">正在讀取事件研究封存…</p>
 </section>
</template>
